code='''\"\"\"Invoice implementation.\"\"\"\nfrom decimal import Decimal, ROUND_HALF_UP\n\nQ = Decimal(\"0.01\")\n\n\ndef _r(x):\n    return x.quantize(Q, rounding=ROUND_HALF_UP)\n\n\ndef _discount_rate(customer):\n    return {\"gold\": Decimal(\"0.05\"), \"silver\": Decimal(\"0.02\")}.get(customer.get(\"tier\"), Decimal(0))\n\n\ndef _tax_rate(customer):\n    return Decimal(0)\n\n\ndef compute_invoice(lines, customer):\n    if not lines:\n        raise ValueError(\"empty lines\")\n    sub = Decimal(0)\n    for l in lines:\n        q = l.get(\"qty\")\n        if not isinstance(q, int) or isinstance(q, bool) or q <= 0:\n            raise ValueError(\"bad qty\")\n        p = Decimal(str(l.get(\"unit_price\")))\n        if p < 0:\n            raise ValueError(\"negative price\")\n        sub += _r(q * p)\n    disc = _r(sub * _discount_rate(customer))\n    tax = _r((sub - disc) * _tax_rate(customer))\n    total = sub - disc + tax\n    return {k: str(_r(v)) for k, v in ((\"subtotal\", sub), (\"discount\", disc), (\"tax\", tax), (\"total\", total))}\n\n\ndef format_money(amount, currency):\n    raise NotImplementedError\n'''
open('/task/workspace/invoice/core.py','w').write(code)
open('/task/workspace/NOTES.md','w').write('Stage1 done: rounding half-up per line, tier gold5/silver2, validation. core.py has _discount_rate/_tax_rate hooks.\n')
